<?php
require_once __DIR__ . '/../config/db.php';require_once __DIR__ . '/../includes/functions.php';require_role(['admin']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$role=$_POST['role']??'customer';if(in_array($role,['admin','employee','customer'],true)){if($id===(int)current_user()['id'] && $role!=='admin')$error='You cannot remove your own admin role while signed in.';else{$st=$pdo->prepare('UPDATE users SET role=? WHERE id=?');$st->execute([$role,$id]);header('Location: users.php');exit;}}}
$users=$pdo->query('SELECT id,username,email,role,created_at FROM users ORDER BY created_at DESC')->fetchAll();$pageTitle='Manage Users';include __DIR__.'/../includes/header.php';
?>
<div class="admin-shell"><h1>USER AND ROLE MANAGEMENT</h1><nav class="admin-nav"><a href="index.php">Dashboard</a></nav><?php if($error): ?><div class="form-error"><?= e($error) ?></div><?php endif; ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Username</th><th>Email</th><th>Created</th><th>Role</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?= e($u['username']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['created_at']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><select name="role"><?php foreach(['customer','employee','admin'] as $r): ?><option value="<?= $r ?>" <?= $u['role']===$r?'selected':'' ?>><?= ucfirst($r) ?></option><?php endforeach; ?></select><button class="btn" style="padding:8px">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
